func fieldMaskFromString[T any](s *string) (*types.FieldMask[T], error) {
	if s == nil {
		return nil, nil
	}
	var paths []string
	if *s != "" {
		paths = strings.Split(*s, ",")
	}
	return types.NewFieldMask[T](paths...)
}
